using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using UnityEngine;

namespace Framework.Movement
{
    /// <summary>
    /// グリッド座標で構成された経路に沿って
    /// 移動制御コンポーネントを操作する。
    /// </summary>
    /// <remarks>
    /// 経路探索および再探索は呼び出し側が担当する。
    /// 使用中は移動方向の制御を本クラスへ委ねる。
    /// 使用終了時にはDisposeを呼び出す。
    /// </remarks>
    public sealed class GridPathFollower : IDisposable
    {
        /// <summary>
        /// 経路追従に使用する移動制御。
        /// </summary>
        private readonly GridMovementController movement;

        /// <summary>
        /// 現在設定されている経路。
        /// </summary>
        private readonly List<Vector2Int> path =
            new List<Vector2Int>();

        /// <summary>
        /// 経路の検証に使用する一時バッファー。
        /// </summary>
        private readonly List<Vector2Int> validationBuffer =
            new List<Vector2Int>();

        /// <summary>
        /// 外部参照用の読み取り専用経路。
        /// </summary>
        private readonly ReadOnlyCollection<Vector2Int>
            readOnlyPath;

        /// <summary>
        /// 現在の経路追従状態。
        /// </summary>
        private GridPathFollowerState state =
            GridPathFollowerState.Idle;

        /// <summary>
        /// 最後に到達した経路上のインデックス。
        /// 未到達の場合は-1。
        /// </summary>
        private int currentPathIndex = -1;

        /// <summary>
        /// 移動中のセル間移動の完了を待っているか。
        /// </summary>
        private bool waitingForPathStart;

        /// <summary>
        /// 本クラスが移動制御を一時停止したか。
        /// </summary>
        private bool ownsMovementPause;

        /// <summary>
        /// 状態変更通知の実行中であるか。
        /// </summary>
        private bool isNotifying;

        /// <summary>
        /// 最後に発生した経路追従の失敗理由。
        /// </summary>
        private GridPathFailureReason lastFailureReason;

        /// <summary>
        /// 経路追従に使用する移動制御。
        /// </summary>
        public GridMovementController Movement => movement;

        /// <summary>
        /// 現在の経路追従状態。
        /// </summary>
        public GridPathFollowerState State => state;

        /// <summary>
        /// 現在設定されている経路。
        /// </summary>
        /// <remarks>
        /// 経路の再設定時に内容が更新される。
        /// スナップショットではない。
        /// </remarks>
        public IReadOnlyList<Vector2Int> Path => readOnlyPath;

        /// <summary>
        /// 経路が設定されているか。
        /// </summary>
        public bool HasPath => path.Count > 0;

        /// <summary>
        /// 経路を追従しているか。
        /// </summary>
        public bool IsFollowing =>
            state == GridPathFollowerState.Following;

        /// <summary>
        /// 経路追従が一時停止中であるか。
        /// </summary>
        public bool IsPaused =>
            state == GridPathFollowerState.Paused;

        /// <summary>
        /// リソースが解放済みであるか。
        /// </summary>
        public bool IsDisposed =>
            state == GridPathFollowerState.Disposed;

        /// <summary>
        /// 最後に到達した経路上のインデックス。
        /// </summary>
        public int CurrentPathIndex => currentPathIndex;

        /// <summary>
        /// 最後に発生した経路追従の失敗理由。
        /// </summary>
        public GridPathFailureReason LastFailureReason =>
            lastFailureReason;

        /// <summary>
        /// 新しい経路を探索する際の開始セル。
        /// </summary>
        /// <remarks>
        /// セル間を移動中の場合は移動先セルを返す。
        /// </remarks>
        public Vector2Int PathStartCell =>
            movement.IsTraversing
                ? movement.TargetCell
                : movement.CurrentCell;

        /// <summary>
        /// 設定された経路の目的地。
        /// 経路未設定の場合は既定値。
        /// </summary>
        public Vector2Int Destination =>
            HasPath
                ? path[path.Count - 1]
                : default;

        /// <summary>
        /// 目的地までに到達する必要があるセル数。
        /// </summary>
        public int RemainingCellCount =>
            HasPath
                ? Math.Max(
                    0,
                    path.Count - currentPathIndex - 1)
                : 0;

        /// <summary>
        /// 経路追従の進捗率。
        /// </summary>
        /// <remarks>
        /// セル到達数を基準とした0から1までの値。
        /// セル間の補間位置は考慮しない。
        /// </remarks>
        public float Progress
        {
            get
            {
                if (state ==
                    GridPathFollowerState.Completed)
                {
                    return 1f;
                }

                if (path.Count <= 1)
                {
                    return 0f;
                }

                return Mathf.Clamp01(
                    (float)currentPathIndex /
                    (path.Count - 1));
            }
        }

        /// <summary>
        /// 経路追従状態が変更された際に通知する。
        /// </summary>
        public event Action<
            GridPathFollowerState,
            GridPathFollowerState> StateChanged;

        /// <summary>
        /// 経路の目的地へ到達した際に通知する。
        /// </summary>
        public event Action<Vector2Int> PathCompleted;

        /// <summary>
        /// 経路追従に失敗した際に通知する。
        /// </summary>
        public event Action<GridPathFailureReason> PathFailed;

        /// <summary>
        /// 経路追従が中断された際に通知する。
        /// </summary>
        public event Action PathCancelled;

        /// <summary>
        /// 経路追従システムを生成する。
        /// </summary>
        /// <param name="movement">
        /// 初期化済みの移動制御コンポーネント
        /// </param>
        /// <exception cref="ArgumentNullException">
        /// 移動制御が指定されていない場合。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 移動制御が初期化されていない場合。
        /// </exception>
        public GridPathFollower(
            GridMovementController movement)
        {
            if (movement == null)
            {
                throw new ArgumentNullException(
                    nameof(movement));
            }

            if (!movement.IsInitialized)
            {
                throw new InvalidOperationException(
                    "移動制御が初期化されていません。");
            }

            this.movement = movement;

            readOnlyPath = path.AsReadOnly();

            // セル到達時に次の移動方向を指示する。
            movement.CellReached += HandleCellReached;

            // 予期しない移動停止を検知する。
            movement.MovementStopped += HandleMovementStopped;

            // 外部からの座標変更を検知する。
            movement.Teleported += HandleTeleported;
        }

        /// <summary>
        /// 新しい経路を設定して追従を開始する。
        /// </summary>
        /// <param name="newPath">
        /// 開始セルと目的地を含むグリッド座標の経路
        /// </param>
        /// <returns>
        /// 有効な経路を設定できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 不正な経路が指定された場合は既存経路を維持する。
        /// 移動中の場合はTargetCellを開始セルとする。
        /// 一時停止中の経路変更は許可しない。
        /// </remarks>
        public bool TrySetPath(
            IReadOnlyList<Vector2Int> newPath)
        {
            if (!CanModify() ||
                IsPaused ||
                movement.IsPaused ||
                newPath == null ||
                newPath.Count == 0)
            {
                return false;
            }

            if (!ValidatePath(newPath))
            {
                return false;
            }

            // 検証成功後にのみ既存経路を変更する。
            path.Clear();
            path.AddRange(validationBuffer);

            validationBuffer.Clear();

            lastFailureReason =
                GridPathFailureReason.None;

            waitingForPathStart =
                movement.IsTraversing;

            currentPathIndex =
                waitingForPathStart ? -1 : 0;

            // 以前の経路による方向要求を破棄する。
            movement.ClearRequestedDirection();

            ChangeState(
                GridPathFollowerState.Following);

            // 移動中の場合は現在の移動区間を完了させる。
            if (waitingForPathStart)
            {
                return true;
            }

            // 開始セルと目的地が同じ場合は即時完了する。
            if (path.Count == 1)
            {
                CompletePath();

                return true;
            }

            return RequestNextDirection();
        }

        /// <summary>
        /// 経路追従を一時停止する。
        /// </summary>
        /// <returns>
        /// 一時停止できた場合はtrue
        /// </returns>
        public bool Pause()
        {
            if (!CanModify() || !IsFollowing)
            {
                return false;
            }

            ownsMovementPause = !movement.IsPaused;

            ChangeState(
                GridPathFollowerState.Paused);

            if (ownsMovementPause)
            {
                movement.Pause();
            }

            return true;
        }

        /// <summary>
        /// 一時停止した経路追従を再開する。
        /// </summary>
        /// <returns>
        /// 再開できた場合はtrue
        /// </returns>
        public bool Resume()
        {
            if (!CanModify() || !IsPaused)
            {
                return false;
            }

            // 外部システムによる停止は解除しない。
            if (!ownsMovementPause &&
                movement.IsPaused)
            {
                return false;
            }

            ChangeState(
                GridPathFollowerState.Following);

            ReleaseMovementPause();

            if (movement.IsTraversing)
            {
                return true;
            }

            return RequestNextDirection();
        }

        /// <summary>
        /// 現在の経路追従を中断する。
        /// </summary>
        /// <returns>
        /// 経路追従を中断できた場合はtrue
        /// </returns>
        /// <remarks>
        /// セル間を移動中の場合は次のセル中心で停止する。
        /// 設定済み経路は確認用として保持する。
        /// </remarks>
        public bool Cancel()
        {
            if (!CanModify() ||
                (!IsFollowing && !IsPaused))
            {
                return false;
            }

            waitingForPathStart = false;

            ChangeState(
                GridPathFollowerState.Cancelled);

            StopMovement();

            ReleaseMovementPause();

            Notify(PathCancelled);

            return true;
        }

        /// <summary>
        /// 経路と実行状態を初期化する。
        /// </summary>
        /// <returns>
        /// 初期化できた場合はtrue
        /// </returns>
        public bool Reset()
        {
            if (!CanModify())
            {
                return false;
            }

            if (IsFollowing || IsPaused)
            {
                Cancel();
            }

            path.Clear();
            validationBuffer.Clear();

            currentPathIndex = -1;
            waitingForPathStart = false;

            lastFailureReason =
                GridPathFailureReason.None;

            ChangeState(
                GridPathFollowerState.Idle);

            return true;
        }

        /// <summary>
        /// 経路追従システムのリソースを解放する。
        /// </summary>
        /// <remarks>
        /// 移動制御コンポーネント自体は破棄しない。
        /// 複数回呼び出しても安全。
        /// </remarks>
        public void Dispose()
        {
            if (IsDisposed)
            {
                return;
            }

            if (isNotifying)
            {
                throw new InvalidOperationException(
                    "イベント通知中は解放できません。");
            }

            bool wasActive =
                IsFollowing || IsPaused;

            // 移動制御からのイベント購読を解除する。
            if (movement != null)
            {
                movement.CellReached -= HandleCellReached;

                movement.MovementStopped -=
                    HandleMovementStopped;

                movement.Teleported -= HandleTeleported;
            }

            path.Clear();
            validationBuffer.Clear();

            currentPathIndex = -1;
            waitingForPathStart = false;

            // 通知より先に解放状態を確定する。
            GridPathFollowerState previousState = state;

            state = GridPathFollowerState.Disposed;

            try
            {
                if (wasActive && movement != null)
                {
                    StopMovement();
                    ReleaseMovementPause();
                }

                Notify(() =>
                    StateChanged?.Invoke(
                        previousState,
                        state));
            }
            finally
            {
                StateChanged = null;
                PathCompleted = null;
                PathFailed = null;
                PathCancelled = null;
            }
        }

        /// <summary>
        /// 指定された経路の有効性を検証する。
        /// </summary>
        /// <param name="newPath">検証対象の経路</param>
        /// <returns>有効な経路の場合はtrue</returns>
        private bool ValidatePath(
            IReadOnlyList<Vector2Int> newPath)
        {
            validationBuffer.Clear();

            if (newPath[0] != PathStartCell)
            {
                return false;
            }

            for (int i = 0; i < newPath.Count; i++)
            {
                Vector2Int position = newPath[i];

                // 開始セルを含め、通行可能性を検証する。
                if (!movement.CanEnterCell(position))
                {
                    validationBuffer.Clear();

                    return false;
                }

                if (i > 0)
                {
                    Vector2Int direction =
                        position - newPath[i - 1];

                    // 上下左右の隣接セルのみ許可する。
                    if (!GridMovementController
                        .IsCardinalDirection(direction))
                    {
                        validationBuffer.Clear();

                        return false;
                    }
                }

                validationBuffer.Add(position);
            }

            return true;
        }

        /// <summary>
        /// 次の経路セルへの移動方向を要求する。
        /// </summary>
        /// <returns>
        /// 移動方向を要求できた場合、
        /// または経路が完了した場合はtrue
        /// </returns>
        private bool RequestNextDirection()
        {
            if (!IsFollowing || !HasPath)
            {
                return false;
            }

            int nextIndex = currentPathIndex + 1;

            if (nextIndex >= path.Count)
            {
                CompletePath();

                return true;
            }

            Vector2Int nextCell = path[nextIndex];

            if (!movement.CanEnterCell(nextCell))
            {
                FailPath(
                    GridPathFailureReason.CellBlocked);

                return false;
            }

            Vector2Int direction =
                nextCell - movement.CurrentCell;

            if (!GridMovementController
                .IsCardinalDirection(direction))
            {
                FailPath(
                    GridPathFailureReason.UnexpectedCell);

                return false;
            }

            if (!movement.RequestDirection(direction))
            {
                FailPath(
                    GridPathFailureReason.DirectionRejected);

                return false;
            }

            return true;
        }

        /// <summary>
        /// セル到達時に経路の進行状態を更新する。
        /// </summary>
        /// <param name="position">到達したセル座標</param>
        private void HandleCellReached(
            Vector2Int position)
        {
            if (!IsFollowing)
            {
                return;
            }

            int expectedIndex =
                waitingForPathStart
                    ? 0
                    : currentPathIndex + 1;

            if (expectedIndex >= path.Count ||
                path[expectedIndex] != position)
            {
                FailPath(
                    GridPathFailureReason.UnexpectedCell);

                return;
            }

            waitingForPathStart = false;

            currentPathIndex = expectedIndex;

            // 目的地到達時は次の移動を開始させない。
            if (currentPathIndex == path.Count - 1)
            {
                CompletePath();

                return;
            }

            // AIの更新を待たず次の方向を要求する。
            RequestNextDirection();
        }

        
        /// <summary>
        /// 予期しない移動停止を処理する。
        /// </summary>
        /// <param name="position">停止したセル座標</param>
        /// <remarks>
        /// 瞬間移動に伴う移動停止は処理対象外とする。
        /// 瞬間移動による経路追従の失敗は
        /// HandleTeleportedで処理する。
        /// </remarks>
        private void HandleMovementStopped(
            Vector2Int position)
        {
            if (!IsFollowing)
            {
                return;
            }

            // 瞬間移動に伴う停止通知は無視する。
            // 後続のTeleportedイベントで失敗を処理する。
            if (movement.IsTeleporting)
            {
                return;
            }

            int nextIndex = currentPathIndex + 1;

            if (nextIndex >= 0 &&
                nextIndex < path.Count &&
                !movement.CanEnterCell(path[nextIndex]))
            {
                FailPath(
                    GridPathFailureReason.CellBlocked);

                return;
            }

            FailPath(
                GridPathFailureReason.MovementStopped);
        }

        /// <summary>
        /// 外部からの座標変更を処理する。
        /// </summary>
        /// <param name="previousPosition">変更前の座標</param>
        /// <param name="newPosition">変更後の座標</param>
        private void HandleTeleported(
            Vector2Int previousPosition,
            Vector2Int newPosition)
        {
            if (!IsFollowing && !IsPaused)
            {
                return;
            }

            FailPath(
                GridPathFailureReason.Teleported);
        }

        /// <summary>
        /// 経路追従を正常完了させる。
        /// </summary>
        private void CompletePath()
        {
            Vector2Int destination = Destination;

            currentPathIndex = path.Count - 1;

            waitingForPathStart = false;

            // 停止イベントより先に完了状態へ変更する。
            ChangeState(
                GridPathFollowerState.Completed);

            StopMovement();

            ReleaseMovementPause();

            Notify(() =>
                PathCompleted?.Invoke(destination));
        }

        /// <summary>
        /// 経路追従を失敗状態へ変更する。
        /// </summary>
        /// <param name="reason">経路追従の失敗理由</param>
        private void FailPath(
            GridPathFailureReason reason)
        {
            if (!IsFollowing && !IsPaused)
            {
                return;
            }

            lastFailureReason = reason;

            waitingForPathStart = false;

            ChangeState(
                GridPathFollowerState.Failed);

            StopMovement();

            ReleaseMovementPause();

            Notify(() =>
                PathFailed?.Invoke(reason));
        }

        /// <summary>
        /// 方向要求を解除し、安全なセル中心で停止する。
        /// </summary>
        private void StopMovement()
        {
            movement.ClearRequestedDirection();

            movement.RequestStop();
        }

        /// <summary>
        /// 本クラスが設定した移動停止を解除する。
        /// </summary>
        private void ReleaseMovementPause()
        {
            if (!ownsMovementPause)
            {
                return;
            }

            ownsMovementPause = false;

            movement.Resume();
        }

        /// <summary>
        /// 経路追従状態を変更する。
        /// </summary>
        /// <param name="newState">変更後の状態</param>
        private void ChangeState(
            GridPathFollowerState newState)
        {
            if (state == newState)
            {
                return;
            }

            GridPathFollowerState previousState = state;

            state = newState;

            Notify(() =>
                StateChanged?.Invoke(
                    previousState,
                    newState));
        }

        /// <summary>
        /// イベントを再入防止付きで通知する。
        /// </summary>
        /// <param name="notification">通知処理</param>
        private void Notify(Action notification)
        {
            bool previousValue = isNotifying;

            isNotifying = true;

            try
            {
                notification?.Invoke();
            }
            finally
            {
                isNotifying = previousValue;
            }
        }

        /// <summary>
        /// 外部から状態を変更できるか確認する。
        /// </summary>
        /// <returns>変更可能な場合はtrue</returns>
        private bool CanModify()
        {
            return !IsDisposed &&
                !isNotifying &&
                movement != null &&
                movement.IsInitialized;
        }
    }
}
